Given a string, we have to find out all its subsequences of it. A String is said to be a subsequence of another String, if it can be obtained by deleting 0 or more character without changing its order.For example, sub-sequences of "geeks" are Examples: Input : abOutput : "", "a", "b", "ab"Input : abcOutput : "", "a", "b", "c", "ab", "ac", "bc", "abc"Try It YourselfTable of ContentPick and Don't Pick Recursive ApproachIncremental ApproachUsing Binary Representation of Numbers from 0 to 2^n – 1Pick and Don't Pick Recursive ApproachWe begin with the last character and for every character, we make two choices, we either pick it or do not pick it and make two recursive calls. This way generate all possible subsequences.
            C++

    #include <bits/stdc++.h>
using namespace std;

// Find all subsequences recursively
void printSubRec(string s, string curr)
{
    // Base Case : s is empty, print 
    // current subsequence
    if (s.empty()) {
        cout << curr << endl;
        return;
    }

    // curr is passed with including
    // the first character of the string
    printSubRec(s.substr(1), curr + s[0]);

    // curr is passed without including
    // the first character of the string
    printSubRec(s.substr(1), curr);
}

// Wrapper method for printSubRec
void printSubs(string s)
{
    string curr = ""; 
    printSubRec(s, curr);
}

// Driver code
int main()
{
    string s = "ab";
    printSubs(s); 
    return 0;
}


